import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import './Aiiot.css'; // Ensure basic resets exist here

const ProjectDetail = () => {
  const { projectId } = useParams();
  const [activeSection, setActiveSection] = useState('overview');

  // Scroll to top on mount
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [projectId]);

  // Handle Scroll Spy
  useEffect(() => {
    const handleScroll = () => {
      const sections = ['overview', 'impact', 'applications', 'contact'];
      const scrollPosition = window.scrollY + 200;

      for (const section of sections) {
        const element = document.getElementById(section);
        if (element && element.offsetTop <= scrollPosition && (element.offsetTop + element.offsetHeight) > scrollPosition) {
          setActiveSection(section);
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 120;
      const elementPosition = element.getBoundingClientRect().top;
      const offsetPosition = elementPosition + window.pageYOffset - offset;
      window.scrollTo({ top: offsetPosition, behavior: 'smooth' });
    }
  };

  // --- UPDATED DATA WITH ONLINE IMAGES & NON-TECHNICAL CONTENT ---
  const projectsData = {
    'intelligent-sensor': {
      title: 'Air Quality Guardian',
      subtitle: 'Know What You Breathe',
      tagline: 'Making invisible threats visible for a healthier life.',
      // Image: Blue sky/clean city
      mainImage: 'https://images.unsplash.com/photo-1532601224476-15c79f2f7a51?q=80&w=2070&auto=format&fit=crop', 
      description: 'Your personal shield against air pollution. This system doesn’t just show numbers; it interprets the air around you to protect your family’s health.',
      fullDescription: `Air pollution is often invisible, but its impact on health is real. Our Intelligent Sensor serves as a health companion for schools, offices, and smart cities. Instead of confusing technical graphs, it translates complex air data into simple health advice—telling you when it's safe to jog, when to close windows, and when the air quality is pristine.`,
      // Custom "Health Impact" data instead of generic features
      healthImpacts: [
        { 
          label: 'PM 2.5 (Fine Particles)', 
          effect: 'Respiratory Health', 
          desc: 'Tiny particles that enter lungs. We alert you before they reach harmful levels.',
          color: '#ef4444', // Red
          icon: '🫁'
        },
        { 
          label: 'CO2 (Carbon Dioxide)', 
          effect: 'Focus & Energy', 
          desc: 'High levels cause drowsiness. We help optimize ventilation for better productivity.',
          color: '#f59e0b', // Amber
          icon: '🧠'
        },
        { 
          label: 'Temperature & Humidity', 
          effect: 'Viral Spread', 
          desc: 'Optimizes indoor climate to reduce the survival rate of airborne viruses.',
          color: '#3b82f6', // Blue
          icon: '🌡️'
        },
        { 
          label: 'Volatile Gases (VOCs)', 
          effect: 'Long-term Safety', 
          desc: 'Detects invisible chemicals from paints or furniture that affect immunity.',
          color: '#8b5cf6', // Purple
          icon: '🧪'
        }
      ],
      applications: [
        { title: 'School Campuses', image: 'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=800&q=80', desc: 'Protecting children during outdoor play.' },
        { title: 'Smart Offices', image: 'https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=800&q=80', desc: 'Boosting employee focus with fresh air.' },
        { title: 'Public Parks', image: 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=800&q=80', desc: 'Real-time safety checks for joggers.' },
      ],
      brochureUrl: '#'
    },
    'water-level': {
      title: 'Flood Alert System',
      subtitle: 'Community Safety First',
      tagline: 'Early warnings that save lives and property.',
      mainImage: 'https://images.unsplash.com/photo-1544413660-2991628f6779?auto=format&fit=crop&w=2000&q=80',
      description: 'A guardian for riverbanks and dams. We provide crucial extra time for communities to prepare before water levels rise dangerously.',
      fullDescription: `Floods often strike with little warning. Our Smart Water Level Monitor acts as a 24/7 watchman. By constantly measuring water depth and predicting trends using smart algorithms, it sends instant alerts to community leaders and phones. It is peace of mind for anyone living near water bodies.`,
      // Generic "Benefits" since it's not AQI
      benefits: [
        { title: 'Instant Alerts', desc: 'Get SMS/App notifications the moment water rises.', icon: '📲' },
        { title: 'Solar Powered', desc: 'Works even when the power grid goes down during storms.', icon: '☀️' },
        { title: 'Predictive', desc: 'Guesses flood risks hours before they happen.', icon: '🔮' },
        { title: 'Rugged Build', desc: 'Designed to withstand heavy rain and storms.', icon: '🛡️' }
      ],
      applications: [
        { title: 'Riverside Villages', image: 'https://images.unsplash.com/photo-1463870635489-082496a7d25d?auto=format&fit=crop&w=800&q=80', desc: 'Evacuation warnings for families.' },
        { title: 'Underpasses', image: 'https://images.unsplash.com/photo-1519501025264-65ba15a82390?auto=format&fit=crop&w=800&q=80', desc: 'Preventing cars from getting stuck.' },
        { title: 'Reservoirs', image: 'https://images.unsplash.com/photo-1524410943962-42da6a603c40?auto=format&fit=crop&w=800&q=80', desc: 'Managing water release safely.' }
      ],
      brochureUrl: '#'
    },
    'digital-water': {
      title: 'Smart Water Network',
      subtitle: 'Save Every Drop',
      tagline: 'Visualizing water flow to stop wastage.',
      mainImage: 'https://images.unsplash.com/photo-1523661858567-5d554ba7398b?auto=format&fit=crop&w=2000&q=80',
      description: 'Imagine seeing inside the pipes underground. We help cities and buildings find leaks instantly and ensure everyone gets enough water.',
      fullDescription: `Water is precious, yet huge amounts are lost to invisible leaks. Our Digital Twin technology creates a live map of your water pipes. It highlights leaks, pressure drops, and usage patterns in real-time. It’s not just about pipes; it’s about sustainability and lowering water bills.`,
      benefits: [
        { title: 'Find Leaks', desc: 'Spot hidden leaks before they damage infrastructure.', icon: '💧' },
        { title: 'Fair Distribution', desc: 'Ensure every home gets equal water pressure.', icon: '⚖️' },
        { title: 'Save Money', desc: 'Drastically reduce wasted water costs.', icon: '💰' },
        { title: 'Remote Control', desc: 'Manage valves from your smartphone.', icon: '📱' }
      ],
      applications: [
        { title: 'Apartment Complexes', image: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=800&q=80', desc: 'Automated billing and leak checks.' },
        { title: 'City Municipalities', image: 'https://images.unsplash.com/photo-1449824913929-49aa711563aa?auto=format&fit=crop&w=800&q=80', desc: 'Managing city-wide supply.' },
        { title: 'Green Hotels', image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', desc: 'Sustainability certification goals.' }
      ],
      brochureUrl: '#'
    },
    'startup-skill': {
      title: 'Innovation Hub',
      subtitle: 'Build The Future',
      tagline: 'From raw ideas to real-world products.',
      mainImage: 'https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=2000&q=80',
      description: 'We don’t just teach technology; we build entrepreneurs. A space for students and creators to access tools, funding, and mentorship.',
      fullDescription: `Got an idea? We have the lab. Our Skill Development program is a launchpad. We provide access to 3D printers, electronics, and expert mentors who have built companies. Whether you want to learn IoT or launch a startup, this is your playground to fail fast and succeed faster.`,
      benefits: [
        { title: 'Hands-on Labs', desc: 'Access to 3D printers and CNC machines.', icon: '🛠️' },
        { title: 'Mentorship', desc: 'Learn from CEOs and industry leaders.', icon: '🤝' },
        { title: 'Funding', desc: 'Connect with investors for your idea.', icon: '💸' },
        { title: 'Career Growth', desc: 'Get certified and job-ready.', icon: '📈' }
      ],
      applications: [
        { title: 'Students', image: 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=800&q=80', desc: 'Final year projects & internships.' },
        { title: 'Aspiring Founders', image: 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80', desc: 'Incubation and office space.' },
        { title: 'Colleges', image: 'https://images.unsplash.com/photo-1562774053-701939374585?auto=format&fit=crop&w=800&q=80', desc: 'Setting up modern innovation cells.' }
      ],
      brochureUrl: '#'
    },
  };

  const project = projectsData[projectId];

  if (!project) {
    return (
      <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', background: '#f8fafc' }}>
        <h2 style={{ color: '#334155' }}>Project not found</h2>
        <Link to="/" style={{ color: '#2563eb', marginTop: '1rem', fontWeight: 600 }}>Back Home</Link>
      </div>
    );
  }

  // --- STYLES (Light & Clean) ---
  const styles = {
    stickyNav: {
      position: 'sticky',
      top: '4.5rem', 
      zIndex: 50,
      backgroundColor: 'rgba(255, 255, 255, 0.85)',
      backdropFilter: 'blur(12px)',
      borderBottom: '1px solid rgba(0,0,0,0.05)',
      boxShadow: '0 4px 20px rgba(0,0,0,0.03)',
      transition: 'all 0.3s ease'
    },
    navItem: (isActive) => ({
      padding: '1.2rem 2rem',
      color: isActive ? '#0284c7' : '#64748b',
      fontWeight: isActive ? 700 : 500,
      borderBottom: isActive ? '3px solid #0284c7' : '3px solid transparent',
      cursor: 'pointer',
      fontSize: '1rem',
      transition: 'all 0.3s ease',
    }),
    sectionTitle: {
      fontSize: '2.5rem',
      fontWeight: 800,
      color: '#0f172a',
      marginBottom: '1rem',
      textAlign: 'center'
    },
    card: {
      background: 'white',
      borderRadius: '1.5rem',
      overflow: 'hidden',
      boxShadow: '0 10px 40px -10px rgba(0,0,0,0.08)',
      transition: 'transform 0.3s ease, box-shadow 0.3s ease',
      cursor: 'default',
      height: '100%'
    }
  };

  return (
    <div style={{ background: '#ffffff', minHeight: '100vh', fontFamily: '"Inter", sans-serif', color: '#334155' }}>
      
      {/* 1. HERO SECTION - Light & Airy */}
      <section style={{ 
        position: 'relative', 
        minHeight: '70vh', 
        display: 'flex', 
        alignItems: 'center', 
        background: '#f8fafc',
        overflow: 'hidden'
      }}>
        <div style={{ maxWidth: '80rem', margin: '0 auto', width: '100%', padding: '2rem', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(400px, 1fr))', alignItems: 'center', gap: '4rem', position: 'relative', zIndex: 10 }}>
          
          {/* Text Side */}
          <div className="hero-text">
             <Link to="/" style={{ display: 'inline-block', marginBottom: '1.5rem', padding: '0.5rem 1rem', background: '#e0f2fe', color: '#0284c7', borderRadius: '2rem', textDecoration: 'none', fontSize: '0.85rem', fontWeight: 600 }}>
              ← Back to Solutions
            </Link>
            <h1 style={{ fontSize: 'clamp(2.5rem, 5vw, 4.5rem)', fontWeight: 900, color: '#0f172a', lineHeight: 1.1, marginBottom: '1.5rem' }}>
              {project.title}
            </h1>
            <h2 style={{ fontSize: '1.5rem', color: '#64748b', fontWeight: 400, marginBottom: '2rem' }}>
              {project.subtitle}
            </h2>
            <div style={{ display: 'flex', gap: '1rem' }}>
              <button onClick={() => scrollToSection('contact')} style={{ padding: '1rem 2rem', background: '#0f172a', color: 'white', border: 'none', borderRadius: '3rem', fontWeight: 600, cursor: 'pointer', boxShadow: '0 10px 20px rgba(15,23,42,0.2)' }}>
                Get Started
              </button>
              <button onClick={() => scrollToSection('impact')} style={{ padding: '1rem 2rem', background: 'white', color: '#0f172a', border: '1px solid #e2e8f0', borderRadius: '3rem', fontWeight: 600, cursor: 'pointer' }}>
                Learn More
              </button>
            </div>
          </div>

          {/* Image Side */}
          <div style={{ position: 'relative' }}>
            <div style={{ position: 'absolute', top: '-20px', right: '-20px', width: '100%', height: '100%', background: '#f1f5f9', borderRadius: '2rem', zIndex: -1 }}></div>
            <img 
              src={project.mainImage} 
              alt={project.title} 
              style={{ width: '100%', borderRadius: '2rem', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.15)', objectFit: 'cover', height: '400px' }} 
            />
          </div>
        </div>
      </section>

      {/* 2. STICKY NAV */}
      <div style={styles.stickyNav}>
        <div style={{ maxWidth: '80rem', margin: '0 auto', display: 'flex', justifyContent: 'center', overflowX: 'auto' }}>
          {['Overview', 'Impact', 'Applications', 'Contact'].map((item) => (
            <div key={item} onClick={() => scrollToSection(item.toLowerCase())} style={styles.navItem(activeSection === item.toLowerCase())}>
              {item}
            </div>
          ))}
        </div>
      </div>

      <div style={{ maxWidth: '70rem', margin: '0 auto', padding: '0 2rem' }}>

        {/* 3. OVERVIEW */}
        <section id="overview" style={{ padding: '6rem 0' }}>
          <div style={{ textAlign: 'center', maxWidth: '50rem', margin: '0 auto' }}>
            <h3 style={{ color: '#0284c7', textTransform: 'uppercase', letterSpacing: '2px', fontWeight: 700, fontSize: '0.9rem', marginBottom: '1rem' }}>The Concept</h3>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 800, color: '#1e293b', marginBottom: '1.5rem' }}>{project.tagline}</h2>
            <p style={{ fontSize: '1.25rem', lineHeight: 1.8, color: '#64748b' }}>{project.fullDescription}</p>
          </div>
        </section>

        {/* 4. IMPACT / HEALTH SECTION (Replaces Technical Features) */}
        <section id="impact" style={{ padding: '4rem 0 6rem 0' }}>
          <h2 style={styles.sectionTitle}>
            {projectId === 'intelligent-sensor' ? 'Health & Safety Impacts' : 'Key Benefits'}
          </h2>
          <p style={{ textAlign: 'center', color: '#64748b', marginBottom: '4rem', maxWidth: '600px', margin: '0 auto 4rem auto' }}>
             {projectId === 'intelligent-sensor' 
               ? 'Understanding how air quality affects your daily life and long-term well-being.'
               : 'Why this solution changes the game for your community.'}
          </p>

          {projectId === 'intelligent-sensor' && project.healthImpacts ? (
            /* AQI SPECIAL LAYOUT */
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '2rem' }}>
              {project.healthImpacts.map((item, idx) => (
                <div key={idx} style={{ ...styles.card, borderTop: `6px solid ${item.color}`, padding: '2rem', display: 'flex', flexDirection: 'column', alignItems: 'center', textAlign: 'center' }}>
                  <div style={{ fontSize: '3rem', marginBottom: '1rem', background: '#f8fafc', width: '80px', height: '80px', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '50%' }}>
                    {item.icon}
                  </div>
                  <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>{item.label}</h3>
                  <span style={{ background: item.color, color: 'white', padding: '0.25rem 0.75rem', borderRadius: '1rem', fontSize: '0.75rem', fontWeight: 700, marginBottom: '1rem' }}>
                    Impacts: {item.effect}
                  </span>
                  <p style={{ color: '#64748b', lineHeight: 1.6 }}>{item.desc}</p>
                </div>
              ))}
            </div>
          ) : (
            /* GENERIC LAYOUT FOR OTHERS */
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '2rem' }}>
              {project.benefits && project.benefits.map((item, idx) => (
                <div key={idx} style={{ ...styles.card, padding: '2.5rem' }}>
                  <div style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>{item.icon}</div>
                  <h3 style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.75rem' }}>{item.title}</h3>
                  <p style={{ color: '#64748b', lineHeight: 1.6 }}>{item.desc}</p>
                </div>
              ))}
            </div>
          )}
        </section>

        {/* 5. APPLICATIONS (Visual & Interactive) */}
        <section id="applications" style={{ padding: '6rem 0', borderTop: '1px solid #f1f5f9' }}>
          <h2 style={styles.sectionTitle}>Where We Deploy</h2>
          <p style={{ textAlign: 'center', color: '#64748b', marginBottom: '4rem' }}>Real-world scenarios where this technology makes a difference.</p>
          
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '2.5rem' }}>
            {project.applications.map((app, idx) => (
              <div 
                key={idx} 
                style={styles.card}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-10px)';
                  e.currentTarget.style.boxShadow = '0 20px 40px rgba(0,0,0,0.1)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow = '0 10px 40px -10px rgba(0,0,0,0.08)';
                }}
              >
                <div style={{ height: '220px', overflow: 'hidden' }}>
                  <img src={app.image} alt={app.title} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                </div>
                <div style={{ padding: '2rem' }}>
                  <h3 style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>
                    {app.title}
                  </h3>
                  <p style={{ color: '#64748b', fontSize: '1rem', lineHeight: 1.6 }}>
                    {app.desc}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* 6. CONTACT / CTA */}
        <section id="contact" style={{ padding: '6rem 0 8rem 0' }}>
          <div style={{ 
            background: 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)', 
            borderRadius: '2rem', 
            padding: '5rem 2rem', 
            textAlign: 'center', 
            color: 'white',
            position: 'relative',
            overflow: 'hidden'
          }}>
             {/* Decorative Circles */}
             <div style={{ position: 'absolute', top: '-100px', left: '-100px', width: '300px', height: '300px', background: '#3b82f6', filter: 'blur(80px)', opacity: 0.3 }}></div>
             <div style={{ position: 'absolute', bottom: '-100px', right: '-100px', width: '300px', height: '300px', background: '#8b5cf6', filter: 'blur(80px)', opacity: 0.3 }}></div>

            <h2 style={{ fontSize: 'clamp(2rem, 4vw, 3rem)', fontWeight: 800, marginBottom: '1.5rem', position: 'relative' }}>
              Interesting? Let's Talk.
            </h2>
            <p style={{ color: '#cbd5e1', fontSize: '1.2rem', marginBottom: '2.5rem', maxWidth: '600px', margin: '0 auto 2.5rem auto', position: 'relative' }}>
              We customize our solutions for your specific environment. Reach out to get a demo or a free consultation.
            </p>
            <div style={{ position: 'relative', display: 'flex', justifyContent: 'center', gap: '1rem', flexWrap: 'wrap' }}>
              <button style={{ padding: '1.2rem 2.5rem', background: '#3b82f6', color: 'white', border: 'none', borderRadius: '3rem', fontWeight: 600, fontSize: '1.1rem', cursor: 'pointer', transition: 'background 0.2s' }}>
                Contact Sales
              </button>
              <button style={{ padding: '1.2rem 2.5rem', background: 'rgba(255,255,255,0.1)', color: 'white', border: '1px solid rgba(255,255,255,0.3)', borderRadius: '3rem', fontWeight: 600, fontSize: '1.1rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                Download Brochure <span>⬇</span>
              </button>
            </div>
          </div>
        </section>

      </div>
    </div>
  );
};

export default ProjectDetail;
